const ResetDevice=(()=>{const e=window.NKA_API_BASE||"/api";async function t(t=!1){const n=localStorage.getItem("nka_token");if(n)try{const s=await fetch(`${e}/device${t?"?full=1":""}`,{method:"DELETE",headers:{Authorization:`Bearer ${n}`}});if(!s.ok){let e=`Erreur ${s.status}`;try{e=(await s.json()).error||e}catch(e){}throw new Error(e)}}catch(e){return void Toast.show(`Purge non confirmée : ${e.message||"serveur inaccessible"}`)}localStorage.clear();try{const e=await caches.keys();await Promise.all(e.map(e=>caches.delete(e)))}catch(e){}try{const e=await(navigator.serviceWorker?.getRegistrations?.())||[];await Promise.all(e.map(e=>e.unregister()))}catch(e){}try{await new Promise(e=>{const t=indexedDB.deleteDatabase("nka-offline-cache");t.onsuccess=t.onerror=t.onblocked=()=>e()})}catch(e){}location.reload()}return{openConfirm:function(){const e=document.createElement("div");e.className="reset-overlay",e.innerHTML='\n      <div class="reset-modal" role="alertdialog" aria-modal="true" aria-labelledby="reset-title">\n        <div class="reset-icon">⚠️</div>\n        <h3 id="reset-title">Réinitialiser ?</h3>\n        <p>Choisissez ce que vous voulez effacer :</p>\n        <div class="reset-actions">\n          <button class="btn btn-outline" id="reset-cancel-btn">Annuler</button>\n          <button class="btn btn-outline" id="reset-soft-btn">Appareil seul<br><small>Garde les bulletins sur le serveur</small></button>\n          <button class="btn btn-danger" id="reset-full-btn">Tout effacer<br><small>Supprime aussi bulletins et PDFs du serveur</small></button>\n        </div>\n      </div>\n    ',document.body.appendChild(e);const n=()=>e.remove();e.addEventListener("click",t=>{t.target===e&&n()}),e.querySelector("#reset-cancel-btn").addEventListener("click",n),e.querySelector("#reset-soft-btn").addEventListener("click",async()=>{const n=e.querySelector("#reset-soft-btn");n.disabled=!0,n.textContent="Réinitialisation...",await t(!1)}),e.querySelector("#reset-full-btn").addEventListener("click",async()=>{const n=e.querySelector("#reset-full-btn");n.disabled=!0,n.textContent="Suppression...",await t(!0)})},resetDevice:t}})();